    'Remote Chrome Endpoint' => 'Extern Chrome-eindpunt',
    'Remove' => 'Verwijderen',
    'Remove the most recently recorded revision? This cannot be undone.' => 'De laatst vastgelegde versie verwijderen? Dit kan niet ongedaan worden gemaakt.',
    'Remove this entry? Your other changes on this page are saved with it.' => 'Dit item verwijderen? Je andere wijzigingen op deze pagina worden er samen mee opgeslagen.',
    'Report Date' => 'Datum van het rapport',
    'Reported against {standard}.' => 'Gerapporteerd volgens {standard}.',
