    'You do not have permission to view this asset.' => 'Je hebt geen toestemming om deze asset te bekijken.',
    'Your Target WCAG Level is {level}, but this jurisdiction requires AA. A statement claiming that standard would be asserting a level the site was never measured against.' => 'Je beoogde WCAG-niveau is {level}, maar dit wettelijk kader vereist AA. Een verklaring die die norm claimt, zou een niveau beweren waaraan de site nooit is gemeten.',
    '{attribute} contains invalid characters.' => '{attribute} bevat ongeldige tekens.',
