    '{n, plural, =1{# question} other{# questions}} across {p, plural, =1{# page} other{# pages}} {n, plural, =1{is} other{are}} still waiting on a person.' => '{n, plural, =1{# vraag} other{# vragen}} op {p, plural, =1{# pagina} other{# pagina’s}} {n, plural, =1{wacht} other{wachten}} nog op een mens.',
    '{n, plural, =1{# remark was reworded without the conformance level changing.} other{# remarks were reworded without the conformance level changing.}}' => '{n, plural, =1{# opmerking is geherformuleerd zonder dat het conformiteitsniveau veranderde.} other{# opmerkingen zijn geherformuleerd zonder dat het conformiteitsniveau veranderde.}}',
